//! Contract vectors generated by the pinned oracle
//! (`tests/fixtures/mutation/generate_contract_vectors.py`).
//!
//! These are **not** byte-differential fixtures (see `mutation_writer.rs` for
//! those). They pin the *semantics* of the two validation seams this tranche
//! added:
//!
//! - `canonicalize_lifecycle_payload`: every canonical lifecycle payload the
//!   pinned producer's own emitters persist must round-trip unchanged (native
//!   canonical form == oracle payload), and every payload the pinned pydantic
//!   models refuse must be refused natively.
//! - `InnerStateDelta::from_json`/`to_json_value`: `WPInnerStateDelta.from_dict`
//!   / `to_dict` parity, including scalar blank normalisation, PID/int
//!   coercion, the `not_applicable` subtask alias, the empty review-override
//!   release sentinel and `release_runtime_claim` truthiness.
//!
//! The fixture records the oracle identity used to produce it. Regenerate with:
//!
//! ```sh
//! PYTHONPATH=src SPEC_KITTY_PACKS_ROOT=$PWD/packs .venv-rust-oracle/bin/python \
//!   crates/sk-status/tests/fixtures/mutation/generate_contract_vectors.py
//! ```

mod mutation_support;

use serde_json::{Value, json};
use sk_status::mutation::{InnerStateDelta, canonicalize_lifecycle_payload};

use mutation_support::{mutation_root, read_json};

fn vectors() -> Value {
    read_json(&mutation_root().join("contract_vectors.json"))
}

#[test]
fn the_fixture_records_the_pinned_oracle_identity() {
    let fixture = vectors();
    assert_eq!(
        fixture["baseline"],
        json!("9aed3a8012cb5eb22c0128b14d525039f95fea7a")
    );
    assert!(
        fixture["oracle"]["spec_kitty_events"]
            .as_str()
            .is_some_and(|version| version == "11.3.0"),
        "oracle events version drifted: {}",
        fixture["oracle"]["spec_kitty_events"]
    );
}

#[test]
fn every_oracle_lifecycle_payload_is_canonical_and_idempotent() {
    let fixture = vectors();
    let lifecycle = fixture["lifecycle"].as_object().expect("lifecycle map");
    assert_eq!(
        lifecycle.len(),
        12,
        "the closed set of twelve lifecycle event types is covered"
    );
    for (event_type, payload) in lifecycle {
        let canonical = canonicalize_lifecycle_payload(event_type, payload)
            .unwrap_or_else(|error| panic!("{event_type} refused: {error}"));
        assert_eq!(
            &canonical, payload,
            "{event_type}: native canonical form must equal the persisted oracle payload"
        );
        let again = canonicalize_lifecycle_payload(event_type, &canonical).expect("idempotent");
        assert_eq!(
            again, canonical,
            "{event_type}: canonicalisation is idempotent"
        );
    }
}

#[test]
fn every_oracle_refused_lifecycle_payload_is_refused_natively() {
    let fixture = vectors();
    let refusals = fixture["lifecycle_refusals"]
        .as_array()
        .expect("refusal vectors");
    assert!(!refusals.is_empty(), "no refusal vectors recorded");
    for case in refusals {
        let event_type = case["event_type"].as_str().expect("event_type");
        let payload = &case["payload"];
        assert!(
            canonicalize_lifecycle_payload(event_type, payload).is_err(),
            "native accepted a payload the oracle refused: {event_type} {payload}"
        );
    }
}

#[test]
fn inner_state_delta_vectors_match_the_baseline_dataclass() {
    let fixture = vectors();
    let cases = fixture["inner_state"]
        .as_array()
        .expect("inner state vectors");
    assert!(!cases.is_empty());
    for case in cases {
        let delta = InnerStateDelta::from_json(&case["input"])
            .unwrap_or_else(|error| panic!("input {} refused: {error}", case["input"]));
        assert_eq!(
            delta.to_json_value(),
            case["canonical"],
            "canonical delta mismatch for input {}",
            case["input"]
        );
        assert_eq!(
            delta.is_empty(),
            case["is_empty"].as_bool().expect("is_empty"),
            "is_empty mismatch for input {}",
            case["input"]
        );
    }
}

#[test]
fn the_claim_policy_metadata_shape_matches_the_pinned_builder() {
    let fixture = vectors();
    let expected = &fixture["claim_policy_metadata"];
    assert_eq!(
        expected,
        &json!({"shell_pid": 4242, "shell_pid_created_at": "", "agent": "claude"})
    );
    // The writer merges this into `policy_metadata` unchanged, then stamps
    // `lane_head` beside it (covered by `mutation_contracts`).
    let keys: Vec<&String> = expected.as_object().unwrap().keys().collect();
    assert_eq!(keys, ["agent", "shell_pid", "shell_pid_created_at"]);
}
